        self.expr = expr
        self.pos = 0
        self.current_char = self.expr[self.pos] if self.expr else None

    def error(self):
        raise Exception("Invalid character in expression")

    def advance(self):
        self.pos += 1
        if self.pos < len(self.expr):
            self.current_char = self.expr[self.pos]
        else:
            self.current_char = None

    def skip_whitespace(self):
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def number(self):
        number_str = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            number_str += self.current_char
            self.advance()
        return float(number_str)

    def factor(self):
        if self.current_char == '(':
            self.advance()
            result = self.expr_term()
            self.advance()  # Skip ')'
            return result
        elif self.current_char.isdigit() or self.current_char == '.':
            return self.number()
        self.error()

    def term(self):
        result = self.factor()
        while self.current_char is not None and self.current_char in '*/':
            op = self.current_char
            self.advance()
            if op == '*':
                result *= self.factor()
            elif op == '/':
                result /= self.factor()
        return result

    def expr_term(self):
        result = self.term()
